def proved(of, theory, theorem):
    """one theorem, or None - and never a raise"""
    return of.get(theory, {}).get(theorem)


def theories(of, theorem):
    """which theories have an answer to a question"""
    return [t for t in of if theorem in of[t]]


def asked(of, theory):
    """every question a theory answers"""
    return list(of.get(theory, {}).keys())
